class Solution:
    def countPairs(self, n: int, edges: list[list[int]]) -> int:
        parent = list(range(n))
        size = [1] * n
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            a, b = find(a), find(b)
            if a == b:
                return
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]
        for u, v in edges:
            union(u, v)
        components = {}
        for i in range(n):
            r = find(i)
            components[r] = size[r]
        result = 0
        remaining = n
        for s in components.values():
            remaining -= s
            result += s * remaining
        return result

